import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"GUI System","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/corelib/gui.md","filePath":"en/modules/corelib/gui.md","lastUpdated":0}`),a={name:`en/modules/corelib/gui.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="gui-system" tabindex="-1">GUI System <a class="header-anchor" href="#gui-system" aria-label="Permalink to “GUI System”">​</a></h1><p>CoreLib provides GUI templates, open requests, session management, slot control, and click handling. Business modules reuse this infrastructure instead of implementing inventory events from scratch.</p><h2 id="used-by" tabindex="-1">Used by <a class="header-anchor" href="#used-by" aria-label="Permalink to “Used by”">​</a></h2><table tabindex="0"><thead><tr><th>Module</th><th>Usage</th></tr></thead><tbody><tr><td>EmakiForge</td><td>Forge GUI, recipe book.</td></tr><tr><td>EmakiStrengthen</td><td>Strengthening GUI, material slots, protection slots.</td></tr><tr><td>EmakiGem</td><td>Inlay, extraction, socket opening, and upgrade GUI.</td></tr><tr><td>EmakiSkills</td><td>Skill panel and trigger-selection GUI.</td></tr><tr><td>EmakiCooking</td><td>Steamer, oven, juicer, and fermentation-barrel GUI.</td></tr><tr><td>EmakiAttribute</td><td>Attribute point allocation GUI.</td></tr><tr><td>EmakiItem</td><td>Item repair GUI.</td></tr><tr><td>EmakiLevel</td><td>Level panel and leaderboard GUI.</td></tr><tr><td>EmakiStorage</td><td>Paged warehouse GUI.</td></tr></tbody></table><h2 id="menu-rendering-backend" tabindex="-1">Menu rendering backend <a class="header-anchor" href="#menu-rendering-backend" aria-label="Permalink to “Menu rendering backend”">​</a></h2><p><code>gui.backend</code> in <code>plugins/EmakiCoreLib/config.yml</code> decides how every Emaki menu is presented:</p><table tabindex="0"><thead><tr><th>Value</th><th>Description</th></tr></thead><tbody><tr><td><code>bukkit</code></td><td>Default. Opens a real server-side container and needs no extra plugin.</td></tr><tr><td><code>packet</code></td><td>CoreLib&#39;s built-in packet-based virtual menu. It reuses the same window when the row count changes, so the cursor is not reset. Requires PacketEvents; falls back to <code>bukkit</code> when it is missing.</td></tr><tr><td><code>auto</code></td><td>Uses <code>packet</code> when PacketEvents is installed, otherwise <code>bukkit</code>.</td></tr></tbody></table><p>The default stays <code>bukkit</code>, so upgrading CoreLib does not change existing menu behaviour.</p><h2 id="template-fields" tabindex="-1">Template fields <a class="header-anchor" href="#template-fields" aria-label="Permalink to “Template fields”">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td>Yes</td><td>Template id used by the module. A blank <code>id</code> makes the whole template parse as invalid.</td></tr><tr><td><code>title</code></td><td>string/object</td><td>No</td><td>Inventory title. MiniMessage strings and TextConfig objects are supported. Defaults to the literal <code>GUI</code>.</td></tr><tr><td><code>gui_type</code></td><td>string</td><td>No</td><td>Container type, given as a Bukkit <code>InventoryType</code> name. Defaults to <code>CHEST</code>; an invalid value falls back to <code>CHEST</code> silently. When the type does not support custom rows, <code>rows</code> is forced to <code>0</code>.</td></tr><tr><td><code>rows</code></td><td>integer</td><td>No</td><td>Inventory rows. Defaults to <code>3</code> and is clamped into <code>1</code>–<code>6</code>, i.e. 9–54 slots.</td></tr><tr><td><code>slots</code></td><td>map</td><td>No</td><td>Slot definitions keyed by slot name. Omitting it yields an empty map rather than an error.</td></tr></tbody></table><h2 id="slot-fields" tabindex="-1">Slot fields <a class="header-anchor" href="#slot-fields" aria-label="Permalink to “Slot fields”">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>key</code></td><td>string</td><td>Slot key used by business code.</td></tr><tr><td><code>slots</code></td><td><code>list&lt;number&gt;</code></td><td>Inventory indexes covered by this slot definition.</td></tr><tr><td><code>type</code></td><td>string</td><td>Business type label, such as <code>input</code>, <code>output</code>, <code>button</code>, or <code>decoration</code>.</td></tr><tr><td><code>item</code></td><td>object</td><td>Shared item definition containing <code>source</code>, <code>amount</code>, and <code>components</code>. Without <code>source</code>, it can act as a pure patch for a runtime item.</td></tr><tr><td><code>sounds</code></td><td>map</td><td>Click sounds keyed by click type.</td></tr></tbody></table><h2 id="unified-item-structure" tabindex="-1">Unified item structure <a class="header-anchor" href="#unified-item-structure" aria-label="Permalink to “Unified item structure”">​</a></h2><p>New configs and bundled defaults only write the nested canonical structure:</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">item</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  source</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">minecraft-anvil</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  amount</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  components</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">    custom_name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;green&gt;Confirm&lt;/green&gt;&#39;</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">    lore</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;gray&gt;Click to execute&lt;/gray&gt;&#39;</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">    item_model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">emaki:confirm</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">    enchantment_glint_override</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">    $unset</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">repairable</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">    $reset</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">attribute_modifiers</span></span></code></pre></div><ul><li><code>source</code> accepts every ItemSource shorthand registered in CoreLib; availability depends on the corresponding resolver/plugin.</li><li>A normal component value means <code>SET</code>; <code>$unset</code> removes a component and <code>$reset</code> restores the material prototype default.</li><li>Component IDs must be valid namespaced keys. IDs without a namespace default to <code>minecraft:</code>, while explicit namespaces are preserved; the same rule applies to <code>$unset</code> / <code>$reset</code> entries. Unknown IDs and invalid values for supported components are configuration errors.</li><li>Known components introduced after the current server version are skipped with a warning without linking newer typed classes.</li><li>Third-party sources are cloned first so source identity, PDC, and unknown components survive; only patches that Paper can safely transfer are applied.</li><li>Legacy <code>item: &lt;source&gt;</code> plus top-level <code>components</code>, <code>display_name</code>, and <code>lore</code> are still readable compatibility inputs. When both forms exist, nested <code>item</code> wins.</li><li>Real player-provided targets, materials, and business outputs remain controlled by session state and are not overwritten by template display items.</li></ul><h3 id="automatic-migration-of-legacy-gui-item-fields" tabindex="-1">Automatic migration of legacy GUI item fields <a class="header-anchor" href="#automatic-migration-of-legacy-gui-item-fields" aria-label="Permalink to “Automatic migration of legacy GUI item fields”">​</a></h3><p>Starting with CoreLib <code>4.5.11</code>, shared <code>gui/*.{yml,yaml}</code> files undergo a pure structural migration before normal <code>YamlDocument</code> loading and <code>GuiTemplateParser</code> parsing. The migration walks candidate configured-item nodes throughout the document, including regular <code>slots</code> and module-specific containers such as <code>pages/buttons</code> and <code>virtual_items</code>.</p><p>The mapping follows the runtime <code>LegacyConfiguredItemConverter</code> contract:</p><ul><li>Legacy <code>material</code>, <code>item_source</code> / <code>item_sources</code>, and scalar <code>item</code> sources move to <code>item.source</code>; <code>amount</code> moves to <code>item.amount</code>.</li><li>Legacy <code>display_name</code>, <code>item_name</code>, <code>lore</code>, <code>custom_model_data</code>, <code>enchantments</code>, <code>item_flags</code>, <code>hidden_components</code>, <code>unbreakable</code>, and related display fields move to <code>item.components</code>.</li><li>Existing canonical <code>item.source</code>, <code>item.amount</code>, and component values win. Legacy values never overwrite modern values in mixed files.</li><li>A candidate containing <code>components.raw</code> or <code>item.components.raw</code> is skipped as a whole so opaque raw component payloads are not rewritten.</li><li>Slot layout, sounds, actions, pagination rules, and other non-target business fields remain unchanged. Running the migration again produces no further changes.</li></ul><p>Before a changed batch is committed, every original file is backed up under the relevant plugin data directory at <code>migration-backups/configured-item-format/&lt;timestamp&gt;/</code>, preserving its path relative to the <code>gui/</code> source directory. The migrated YAML is written to a sibling temporary file and parsed again before replacement. If writing, validation, or replacement fails, the original remains intact or is restored from the batch backup, and GUI loading does not continue with an unverified migrated result. BoostedYAML preserves comments on untouched business nodes where its comment model allows, but a full configuration backup is still recommended before production upgrades.</p><p>This compatibility layer does not read version values from <code>config.yml</code>, language files, or plugin descriptors, and it is not version-gated. It runs solely when legacy fields are present. The implementation is contained in CoreLib&#39;s <code>item.migration.configureditem</code> package, with <code>GuiTemplateLoader</code> as the only GUI production bridge, so it can be removed as a unit after the compatibility window without leaving legacy rules in <code>YamlFiles</code>, <code>YamlDirectoryLoader</code>, or canonical parsers.</p><h2 id="click-types" tabindex="-1">Click types <a class="header-anchor" href="#click-types" aria-label="Permalink to “Click types”">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>CLICK</code></td><td>Generic click, used as the fallback when no specific type matches.</td></tr><tr><td><code>LEFTCLICK</code></td><td>Left click.</td></tr><tr><td><code>RIGHTCLICK</code></td><td>Right click.</td></tr><tr><td><code>SHIFT_LEFTCLICK</code></td><td>Shift + left click.</td></tr><tr><td><code>SHIFT_RIGHTCLICK</code></td><td>Shift + right click.</td></tr><tr><td><code>MIDDLECLICK</code></td><td>Middle click.</td></tr><tr><td><code>DOUBLECLICK</code></td><td>Double click.</td></tr><tr><td><code>NUMBER_KEY</code></td><td>Number-key hotbar swap.</td></tr><tr><td><code>SWAP_OFFHAND</code></td><td>Offhand swap key (F by default).</td></tr><tr><td><code>DROP</code></td><td>Drop key (Q by default).</td></tr><tr><td><code>CONTROL_DROP</code></td><td>Ctrl + drop key.</td></tr></tbody></table><p>Every type above can be used as a <code>sounds</code> key.</p><p>Sound lookup has three levels: an exact match on the current click type first; then one retry through the legacy mapping (<code>SHIFT_LEFTCLICK</code> and <code>DOUBLECLICK</code> fall back to <code>LEFTCLICK</code>, <code>SHIFT_RIGHTCLICK</code> falls back to <code>RIGHTCLICK</code>); only then does it fall back to <code>CLICK</code>.</p><h2 id="gui-sessions" tabindex="-1">GUI sessions <a class="header-anchor" href="#gui-sessions" aria-label="Permalink to “GUI sessions”">​</a></h2><p>A GUI session records the state of the menu a player currently has open. CoreLib manages sessions itself; business modules handle interaction logic through the <code>GuiSessionHandler</code> interface.</p><p>A session tracks:</p><ul><li>Which recipe or flow the player is working on.</li><li>Which slots are input slots (items may be placed) and which forbid taking items out.</li><li>Which business flow a button click should invoke.</li><li>Whether input items must be returned when the menu closes.</li><li>Temporary state data for the current menu.</li></ul><p>The point of the session is to stop players duplicating items or bypassing a flow through rapid clicking, shift-clicking, dragging, or an abnormal close.</p><h2 id="slot-index-reference" tabindex="-1">Slot index reference <a class="header-anchor" href="#slot-index-reference" aria-label="Permalink to “Slot index reference”">​</a></h2><p>Slot indexes for a six-row inventory:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Row 1:  0  1  2  3  4  5  6  7  8</span></span>
<span class="line"><span>Row 2:  9 10 11 12 13 14 15 16 17</span></span>
<span class="line"><span>Row 3: 18 19 20 21 22 23 24 25 26</span></span>
<span class="line"><span>Row 4: 27 28 29 30 31 32 33 34 35</span></span>
<span class="line"><span>Row 5: 36 37 38 39 40 41 42 43 44</span></span>
<span class="line"><span>Row 6: 45 46 47 48 49 50 51 52 53</span></span></code></pre></div><p>Frequently used positions:</p><ul><li>Centre of a six-row menu: <code>22</code> (middle of row 3) or <code>31</code> (middle of row 4).</li><li>Bottom centre: <code>49</code>.</li><li>Corners: <code>0</code>, <code>8</code>, <code>45</code>, <code>53</code>.</li></ul><h2 id="minimessage-and-colours" tabindex="-1">MiniMessage and colours <a class="header-anchor" href="#minimessage-and-colours" aria-label="Permalink to “MiniMessage and colours”">​</a></h2><p>Use MiniMessage consistently for GUI text:</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">item</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  source</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">minecraft-smithing_table</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  components</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">    minecraft:custom_name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;gold&gt;Legendary Forge&#39;</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">    minecraft:lore</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;gray&gt;Insert the blueprint, materials, and target gear.&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;yellow&gt;Click to start forging.&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;dark_gray&gt;Cost: &lt;white&gt;500 coins&#39;</span></span></code></pre></div><p>Common MiniMessage tags:</p><table tabindex="0"><thead><tr><th>Tag</th><th>Effect</th></tr></thead><tbody><tr><td><code>&lt;red&gt;</code></td><td>Red text</td></tr><tr><td><code>&lt;green&gt;</code></td><td>Green text</td></tr><tr><td><code>&lt;gold&gt;</code></td><td>Gold text</td></tr><tr><td><code>&lt;gray&gt;</code></td><td>Grey text</td></tr><tr><td><code>&lt;dark_gray&gt;</code></td><td>Dark grey text</td></tr><tr><td><code>&lt;yellow&gt;</code></td><td>Yellow text</td></tr><tr><td><code>&lt;aqua&gt;</code></td><td>Aqua text</td></tr><tr><td><code>&lt;bold&gt;</code></td><td>Bold</td></tr><tr><td><code>&lt;italic&gt;</code></td><td>Italic</td></tr><tr><td><code>&lt;strikethrough&gt;</code></td><td>Strikethrough</td></tr><tr><td><code>&lt;gradient:gold:yellow&gt;</code></td><td>Gradient</td></tr></tbody></table><p>Where a module still accepts legacy colour codes (<code>&amp;a</code>, <code>§b</code>), migrate to MiniMessage over time to keep one style.</p><h2 id="editing-advice" tabindex="-1">Editing advice <a class="header-anchor" href="#editing-advice" aria-label="Permalink to “Editing advice”">​</a></h2><ol><li>Change display text first.</li><li>Then move decorative slots.</li><li>Adjust functional slots only after confirming the layout.</li><li>Test shift-click, drag, double-click, close handling, and full-inventory cases after each GUI change.</li></ol>`,44)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};